// The action table (SPEC 7.1): one typed constant from which the CLI subcommands, the MCP tool
// list, the window API's describe().actions, the OpenAPI document, the palette entries and the
// skills' reference tables are generated by `pnpm generate:contracts`. Every entry is declared
// now, including the ones whose implementation lands later; the dispatcher answers
// not_implemented (HTTP 501) for those (MILESTONES M1 item 3). Every mutating action takes
// baseRevision and rejects a stale one with 409 and the current document.
import { z } from 'zod';
import { assetSchema, assetSourceSchema, assetTreatmentSchema, ASSET_ROLES } from './assets.ts';
import { blockSchema } from './blocks.ts';
import { sectionSchema, slideSchema, SLIDE_KINDS, SLOT_NAMES } from './deck.ts';
import { exportReportSchema } from './export.ts';
import { findingSchema } from './findings.ts';
import { blockIdSchema, slugSchema } from './ids.ts';
import { leaseSchema, mutationSchema, versionSchema } from './mutations.ts';
import { renderRecordSchema } from './render.ts';
import { RULE_IDS } from './rules.ts';

export type Transport = 'cli' | 'mcp' | 'http' | 'window';
export const TRANSPORTS = ['cli', 'mcp', 'http', 'window'] as const;
export const ALL_TRANSPORTS: ReadonlyArray<Transport> = TRANSPORTS;

export type Milestone = 'M1' | 'M2' | 'M3' | 'M4' | 'M5' | 'M6';

/** The palette groups (SPEC 6.1) and the docs sections. */
export type ActionGroup =
  | 'deck'
  | 'slide'
  | 'block'
  | 'asset'
  | 'render'
  | 'lint'
  | 'version'
  | 'export'
  | 'view'
  | 'studio';

export type ActionCli = {
  /** The documented command; `<name>` tokens are positionals named after input keys. */
  usage: string;
  /** The input key read from stdin when the usage ends in `< file.json`. */
  stdin?: string;
};

export type ActionSpec = {
  id: ActionId;
  label: string;
  /** One sentence of documentation. */
  doc: string;
  group: ActionGroup;
  mutates: boolean;
  transports: ReadonlyArray<Transport>;
  milestone: Milestone;
  input: z.ZodType;
  output: z.ZodType;
  cli?: ActionCli;
  /** The MCP tool name, deck_<action>. */
  mcp?: string;
  /** An input that parses; the coverage test runs every example through `input`. */
  example: unknown;
};

export const ACTION_IDS = [
  'deck.info',
  'slide.list',
  'slide.get',
  'slide.insert',
  'slide.remove',
  'slide.move',
  'slide.update',
  'slide.replace',
  'block.set',
  'block.insert',
  'block.remove',
  'block.move',
  'section.set',
  'slide.lease',
  'asset.add',
  'asset.dither',
  'asset.capture',
  'material.capture',
  'render.slide',
  'render.sheet',
  'lint.run',
  'fix.run',
  'diff.run',
  'version.save',
  'version.list',
  'version.restore',
  'judge.bundle',
  'view.goto',
  'view.mode',
  'view.theme',
  'view.present',
  'export.run',
  'build.run',
  'import.run',
  'validate.run',
  'source.read',
  'source.apply',
  'controls.list',
  'control.activate',
  'control.set',
  'artifact.download',
] as const;

export type ActionId = (typeof ACTION_IDS)[number];

// ---------------------------------------------------------------------------------------------
// Shared pieces

const baseRevision = z
  .number()
  .int()
  .nonnegative()
  .describe('The revision the caller read; a stale value is rejected with 409');
const revision = z.number().int().nonnegative();
const theme = z.enum(['light', 'dark']);
const themes = z.array(theme).min(1).describe('One or both themes');
const slideIdsOrAll = z
  .union([z.literal('all'), z.array(slugSchema).min(1)])
  .describe("Slide ids, or 'all'");
const slotSchema = z.enum([...SLOT_NAMES, 'plate']);

export const outlineSchema = z.array(
  z.strictObject({
    id: slugSchema,
    name: z.string(),
    slides: z.array(
      z.strictObject({
        id: slugSchema,
        n: z.number().int().positive(),
        title: z.string(),
        kind: z.enum(SLIDE_KINDS),
      }),
    ),
  }),
);

export const slideResultSchema = z.strictObject({
  slide: slideSchema,
  revision,
  findings: z.array(findingSchema),
});

const slideListRow = z.strictObject({
  id: slugSchema,
  n: z.number().int().positive(),
  section: slugSchema,
  title: z.string(),
  kind: z.enum(SLIDE_KINDS),
  lint: z.strictObject({ s3: z.number().int().nonnegative(), s2: z.number().int().nonnegative() }),
});

export const viewStateSchema = z.strictObject({
  slideId: slugSchema,
  n: z.number().int().positive(),
  mode: z.enum(['slide', 'grid', 'book']),
  theme,
  present: z.boolean(),
  edit: z.boolean().optional(),
});

const empty = z.strictObject({});

const A = ALL_TRANSPORTS;
const noWindow: ReadonlyArray<Transport> = ['cli', 'mcp', 'http'];

function action(spec: ActionSpec): ActionSpec {
  return spec;
}

