/** Actions in table order. */
export function actionsInOrder(): ActionSpec[] {
  return ACTION_IDS.map((id) => ACTIONS[id]);
}

export function actionsOn(transport: Transport): ActionSpec[] {
  return actionsInOrder().filter((spec) => spec.transports.includes(transport));
}

export function isActionId(value: string): value is ActionId {
  return (ACTION_IDS as ReadonlyArray<string>).includes(value);
}
